def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> str:
        # Remove hyphens and convert to list of characters
        chars = isbn.replace('-', '')
        total = 0
        for i in range(9):
            total += int(chars[i]) * (10 - i)
        checksum = 11 - (total % 11)
        return 'X' if checksum == 10 else str(checksum % 11)

    try:
        # Validate format
        if len(isbn) != 13 or isbn[1] != '-' or isbn[5] != '-' or isbn[11] != '-':
            raise ValueError("Invalid ISBN format")

        # Extract parts
        prefix, group, registrant, publication, checksum = isbn.split('-')

        # Calculate expected checksum
        expected_checksum = calculate_checksum(isbn[:-1])

        # Compare and return result
        if checksum == expected_checksum:
            return "Right"
        else:
            return f"{prefix}-{group}-{registrant}-{expected_checksum}"

    except Exception as e:
        return f"Error: {str(e)}"

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    if M <= 0 or N <= 0 or K < 0 or L < 0 or D < 0:
        raise ValueError("Invalid dimensions or number of aisles/chatting pairs.")
    if any(not (1 <= x <= M and 1 <= y <= N and 1 <= p <= M and 1 <= q <= N) for x, y, p, q in chatting_pairs):
        raise ValueError("Chatting pairs are out of classroom bounds.")

    horizontal_separations = [0] * (M + 1)
    vertical_separations = [0] * (N + 1)

    for x, y, p, q in chatting_pairs:
        if x == p:  # Same row, vertical aisle can separate
            min_col, max_col = min(y, q), max(y, q)
            for col in range(min_col + 1, max_col):
                vertical_separations[col] += 1
        elif y == q:  # Same column, horizontal aisle can separate
            min_row, max_row = min(x, p), max(x, p)
            for row in range(min_row + 1, max_row):
                horizontal_separations[row] += 1

    # Find the top K horizontal and L vertical positions
    top_horizontal = sorted(range(1, M + 1), key=lambda x: horizontal_separations[x], reverse=True)[:K]
    top_vertical = sorted(range(1, N + 1), key=lambda x: vertical_separations[x], reverse=True)[:L]

    return (' '.join(map(str, top_horizontal)), ' '.join(map(str, top_vertical)))

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Number of students must be positive and number of passes must be non-negative.")
    if n == 1:
        return 1 if m == 0 else 0

    # dp[i][j] will be the number of ways to reach student i after j passes
    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][0] = 1

    for passes in range(1, m + 1):
        for student in range(n):
            left_neighbor = (student - 1) % n
            right_neighbor = (student + 1) % n
            dp[student][passes] = dp[left_neighbor][passes - 1] + dp[right_neighbor][passes - 1]

    return dp[0][m]

